import React from "react";
import { Link } from "react-router-dom";

export default function LandingPage() {
  return (
    <div className="landing-hero">
      <div>
        <div style={{ fontSize: "4rem", marginBottom: "1rem" }}>🧠</div>
        <h1>Stroke Risk Prediction</h1>
        <p>
          Early detection saves lives. Our AI-powered tool analyses your health
          indicators to assess stroke risk and connect you with specialists.
        </p>
        <div className="landing-actions">
          <Link to="/login/patient" className="btn btn-white">I'm a Patient</Link>
          <Link to="/login/doctor" className="btn btn-outline" style={{ borderColor: "#fff", color: "#fff" }}>
            I'm a Doctor
          </Link>
        </div>
        <p style={{ marginTop: "2rem", fontSize: ".85rem", opacity: .7 }}>
          Don't have an account?{" "}
          <Link to="/signup/patient" style={{ color: "#fff", textDecoration: "underline" }}>Sign up as patient</Link>
          {" "} or{" "}
          <Link to="/signup/doctor" style={{ color: "#fff", textDecoration: "underline" }}>sign up as doctor</Link>
        </p>
      </div>
    </div>
  );
}
